"""
    Recursively access nested dictionaries

    Args:
        dictionary: nested dictionary
        *keys: the keys to access within the nested dictionaries
        default: the default value if dictionary is ``None`` or it doesn't contain
            the keys

    Returns:
        None if we can't access to all the keys, else dictionary[key_0][key_1][...][key_n]
    """
def safe_lookup(dictionary: Any, *keys: Any, `default: Any = None) -> object {
    if (dictionary is None) {
        return `default;
    }
    for key in keys {
        dictionary = dictionary.get(key);
        if (dictionary is None) {
            return `default;
        }
    }
    return dictionary;
}

"""
    https://www.quora.com/In-laymans-terms-what-is-the-difference-between-a-bubble-sort-and-an-insert-sort
    http://stackoverflow.com/questions/17270628/insertion-sort-vs-bubble-sort-algorithms

    Every Iteration, it will try to bubble the Max number to the end of the list
    :param l:
    :param debug:
    :return:
    """
def bubble_sort(l: Any, debug: Any = True) -> object {
    for i in range(len(l)) {
        for j in range(0, (len(l) - i - 1)) {
            if (l[j] > l[(j + 1)]) {
                (l[j], l[(j + 1)]) = (l[(j + 1)], l[j]);
            }
        }
        if debug {
            print('iteration {}'.format(i), l);
        }
    }
    return l;
}

